class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [float('inf')] * (n + 1)

        for i in range(n + 1):
            if s[:i] in dictionary:
                dp[i] = 0

            if dp[i] == float('inf'):
                dp[i] = dp[i - 1] + 1
            else:
                dp[i] = min(dp[i], dp[i - 1] + 1)

        return n - dp[n]
